insert into public.species (slug,name,latin,category_id,kind,difficulty,temperament,description,facts,keywords,is_rare,status) values
('trichromis-salvini','Salvini Cichlid','Trichromis salvini','orta-amerika','fish','Orta','Agresif, bölgeci','Sarı zemin üzerindeki siyah bantları ve kırmızı tonlarıyla dikkat çeker. Üreme döneminde oldukça bölgeci ve sert olabilir.','[["Yetişkin boy", "18 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "250 L"], ["Huy", "Agresif, bölgeci"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Agresif"]]'::jsonb,array['salvini cichlid','salvini','trichromis salvini','cichlasoma salvini','yellow belly cichlid']::text[],false,'published'),
('rocio-octofasciata','Jack Dempsey','Rocio octofasciata','orta-amerika','fish','Orta','Agresif, bölgeci','Koyu gövdesi üzerindeki metalik mavi-yeşil benekleriyle tanınan klasik Orta Amerika cikletidir. Güçlü karakteri nedeniyle uygun hacim ve tank arkadaşı seçimi ister.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "22–30 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "300 L"], ["Huy", "Agresif, bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Agresif, Renkli"]]'::jsonb,array['jack dempsey','rocio octofasciata','octofasciatum','dempsey ciklet']::text[],false,'published'),
('rocio-octofasciata-electric-blue-jack-dempsey','Electric Blue Jack Dempsey','Rocio octofasciata ''Electric Blue Jack Dempsey''','orta-amerika','fish','Zor','Yarı agresif–agresif','Jack Dempsey''nin seçilimle yaygınlaşmış parlak mavi ticari formudur. Standart forma göre daha hassas olabildiği için stabil su koşulları önemlidir.','[["Yetişkin boy", "22 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.8"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif–agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Hassas"]]'::jsonb,array['electric blue jack dempsey','ebjd','blue dempsey','rocio octofasciata']::text[],false,'published'),
('amphilophus-citrinellus','Midas Cichlid','Amphilophus citrinellus','orta-amerika','fish','Orta','Çok agresif','İri gövdesi, güçlü çeneleri ve farklı renk morflarıyla tanınır. Akvaryumda çok bölgeci olabilir ve büyük hacim gerektirir.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "450 L"], ["Huy", "Çok agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Agresif"]]'::jsonb,array['midas cichlid','amphilophus citrinellus','midas ciklet','citrinellus']::text[],false,'published'),
('amphilophus-labiatus','Red Devil','Amphilophus labiatus','orta-amerika','fish','Orta','Çok agresif','Kalın dudaklı yapısı ve turuncu-kırmızı renk morflarıyla bilinen iri bir ciklettir. Güçlü agresyonu nedeniyle çoğu akvaryumda tek tür/tek birey yaklaşımı daha güvenlidir.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "450 L"], ["Huy", "Çok agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Agresif"]]'::jsonb,array['red devil','amphilophus labiatus','labiatus','kırmızı şeytan ciklet']::text[],false,'published'),
('amphilophus-trimaculatus','Trimac Cichlid','Amphilophus trimaculatus','orta-amerika','fish','Orta','Çok agresif','Gövdesindeki üç belirgin koyu leke ve kırmızı tonlarıyla tanınan güçlü bir avcı ciklettir. Büyük hacim ve sağlam dekor gerektirir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "500 L"], ["Huy", "Çok agresif"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Agresif, İri Yapılı"]]'::jsonb,array['trimac cichlid','trimac','amphilophus trimaculatus','three spot cichlid','trimaculatus']::text[],true,'published'),
('cryptoheros-sajica','Sajica / T-Bar Cichlid','Cryptoheros sajica','orta-amerika','fish','Kolay','Yarı agresif','Gövdesindeki T biçimli koyu desenle tanınan, orta boy ve görece yönetilebilir bir Orta Amerika cikletidir. Eş tutunca bölge savunur.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Çift Yaşayan, Orta Boy"]]'::jsonb,array['sajica / t-bar cichlid','sajica','cryptoheros sajica','t bar cichlid','t-bar ciklet']::text[],false,'published'),
('amatitlania-siquia','Honduran Red Point','Amatitlania siquia','orta-amerika','fish','Kolay','Yarı agresif, bölgeci','Convict grubuna benzeyen fakat mavi tonlarıyla dikkat çeken küçük-orta boy bir ciklettir. Dayanıklı ve üretimi görece kolaydır.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif, bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Dayanıklı, Çift Yaşayan"]]'::jsonb,array['honduran red point','hrp','amatitlania siquia','siquia cichlid']::text[],false,'published'),
('cryptoheros-nanoluteus','Nanoluuteus','Cryptoheros nanoluteus','orta-amerika','fish','Orta','Yarı agresif','Altın sarısı gövdesi ve küçük boyuyla dikkat çeken Panama kökenli bir ciklettir. Daha büyük ve saldırgan Orta Amerika türlerinden uzak tutulmalıdır.','[["Yetişkin boy", "10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "100 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Küçük Yapılı, Renkli"]]'::jsonb,array['nanoluuteus','nanoluteus','cryptoheros nanoluteus','yellow convict','sarı cüce ciklet']::text[],true,'published'),
('cryptoheros-cutteri','Cutteri Cichlid','Cryptoheros cutteri','orta-amerika','fish','Kolay','Yarı agresif','Mavi-gri gövdesindeki koyu bantlarla tanınan kompakt bir ciklettir. Eşleştiğinde yavrularını güçlü biçimde korur.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Çift Yaşayan, Dayanıklı"]]'::jsonb,array['cryptoheros cutteri','cutteri cichlid','cutteri','blue eyed cichlid']::text[],false,'published'),
('hypsophrys-nicaraguensis','Nicaraguan Cichlid','Hypsophrys nicaraguensis','orta-amerika','fish','Orta','Yarı agresif','Dişilerde ve erkeklerde farklılaşan canlı sarı, turuncu ve mavi tonlarıyla dikkat çeker. İri olmasına rağmen birçok büyük Orta Amerika türünden daha yönetilebilir karakterlidir.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "350 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, İri Yapılı"]]'::jsonb,array['nicaraguan cichlid','hypsophrys nicaraguensis','nicaraguense','nicaragua ciklet']::text[],false,'published'),
('herotilapia-multispinosa','Rainbow Cichlid','Herotilapia multispinosa','orta-amerika','fish','Kolay','Görece barışçıl, bölgeci','Sarı-turuncu renkleri ve nispeten sakin yapısıyla topluluk tipi büyük ciklet akvaryumlarına daha uygun seçeneklerden biridir. Üreme döneminde renkleri koyulaşır.','[["Yetişkin boy", "13 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Görece barışçıl, bölgeci"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Barışçıl, Renkli"]]'::jsonb,array['rainbow cichlid','herotilapia multispinosa','multispinosa','gökkuşağı ciklet']::text[],false,'published'),
('cryptoheros-spilurus','Blue Sifter / Spilurum','Cryptoheros spilurus','orta-amerika','fish','Kolay','Yarı agresif','Mavi-gri gövde ve dikey bantlarla tanınan, orta boy bir Orta Amerika cikletidir. Üreme döneminde çiftler belirgin alan savunması yapar.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Çift Yaşayan, Çizgili"]]'::jsonb,array['blue sifter / spilurum','cryptoheros spilurus','spilurum','blue eye cichlid','spilurus cichlid']::text[],true,'published'),
('nandopsis-tetracanthus','Cuban Cichlid','Nandopsis tetracanthus','orta-amerika','fish','Zor','Çok agresif','Küba''ya özgü, siyah-beyaz desenli iri ve güçlü bir ciklettir. Sert karakteri ve büyük boyutu nedeniyle deneyimli hobicilere uygundur.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "450 L"], ["Huy", "Çok agresif"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Agresif, Nadir Tür"]]'::jsonb,array['cuban cichlid','nandopsis tetracanthus','tetracanthus','kuba cikleti']::text[],true,'published'),
('nandopsis-haitiensis','Haitian Cichlid / Odo','Nandopsis haitiensis','orta-amerika','fish','Zor','Çok agresif','Hispaniola kökenli, koyu desenli ve iri bir ciklettir. Su kalitesi bozulmasına hassas olabilmesi ve agresyonu nedeniyle ileri seviye bakım ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "500 L"], ["Huy", "Çok agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Nadir Tür, Hassas"]]'::jsonb,array['haitian cichlid / odo','haitian cichlid','nandopsis haitiensis','haitiensis','black nasty cichlid']::text[],true,'published'),
('herichthys-cyanoguttatus','Texas Cichlid','Herichthys cyanoguttatus','orta-amerika','fish','Orta','Agresif','İnci benzeri mavi-yeşil benekleriyle tanınan, ABD''ye doğal olarak ulaşan az sayıdaki ciklet türünden biridir. Güçlü bölgecilik gösterebilir.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "20–28 °C"], ["pH", "6.5–8.5"], ["Min. akvaryum", "400 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Agresif"]]'::jsonb,array['texas cichlid','herichthys cyanoguttatus','cyanoguttatus','texas ciklet']::text[],false,'published'),
('herichthys-pearsei','Pearsei','Herichthys pearsei','orta-amerika','fish','Orta','Yarı agresif','İri, yüksek gövdeli ve büyük ölçüde bitkisel beslenmeye eğilimli bir ciklettir. Genellikle benzer boydaki birçok Orta Amerika devine göre daha sakin olabilir.','[["Yetişkin boy", "40 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "700 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Otçul ağırlıklı omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Otçul"]]'::jsonb,array['pearsei','herichthys pearsei','pantano cichlid','pearsei cichlid']::text[],true,'published'),
('trichromis-bocourti','Bocourti','Trichromis bocourti','orta-amerika','fish','Orta','Yarı agresif','Sarı-altın tonları ve iri gövdesiyle dikkat çeken Orta Amerika cikletidir. Güçlü fakat çoğu dev yırtıcı tür kadar aşırı agresif değildir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "600 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Renkli"]]'::jsonb,array['bocourti','trichromis bocourti','chisel tooth cichlid','bocourti cichlid']::text[],true,'published'),
('vieja-melanura','Vieja melanura','Vieja melanura','orta-amerika','fish','Orta','Yarı agresif–agresif','Kırmızı, turuncu, mavi ve siyah tonların birleştiği iri ve gösterişli bir Vieja türüdür. Büyük hacim ve güçlü filtrasyon gerektirir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "600 L"], ["Huy", "Yarı agresif–agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, İri Yapılı"]]'::jsonb,array['vieja melanura','melanura','redhead cichlid','vieja synspila']::text[],false,'published'),
('vieja-bifasciata','Vieja bifasciata','Vieja bifasciata','orta-amerika','fish','Orta','Agresif','Kırmızı baş ve gövde tonlarıyla dikkat çeken iri bir Vieja türüdür. Yetişkin erkekler oldukça güçlü ve bölgeci olabilir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "600 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Renkli"]]'::jsonb,array['vieja bifasciata','bifasciata','red head vieja','vieja cichlid']::text[],true,'published'),
('vieja-hartwegi','Vieja hartwegi','Vieja hartwegi','orta-amerika','fish','Orta','Agresif','Güçlü gövdesi ve kırmızımsı yüz bölgesiyle bilinen büyük bir Vieja türüdür. Geniş taban alanı ve dikkatli eşleştirme ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "500 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Bölgeci"]]'::jsonb,array['vieja hartwegi','hartwegi','vieja cichlid','tailbar cichlid']::text[],true,'published'),
('vieja-zonata','Vieja zonata','Vieja zonata','orta-amerika','fish','Orta','Agresif','Mavi-yeşil ve kırmızı tonlarıyla gösterişli, iri bir Vieja türüdür. Erişkinlerde tür içi agresyon belirginleşebilir.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "500 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Bölgeci"]]'::jsonb,array['vieja zonata','zonata','oaxaca cichlid','vieja cichlid']::text[],true,'published'),
('vieja-maculicauda','Black Belt Cichlid','Vieja maculicauda','orta-amerika','fish','Orta','Yarı agresif–agresif','Gövdesini çevreleyen geniş siyah bant ve kırmızı tonlarıyla tanınır. Büyük, güçlü ve bitkisel besine belirgin ilgi gösteren bir ciklettir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "600 L"], ["Huy", "Yarı agresif–agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Siyah Bantlı"]]'::jsonb,array['black belt cichlid','vieja maculicauda','maculicauda','blackbelt vieja']::text[],false,'published'),
('vieja-regani','Regani Cichlid','Vieja regani','orta-amerika','fish','Orta','Yarı agresif–agresif','Geniş gövdeli ve parlak renkli bir Vieja türüdür. Büyük akvaryumlarda çift veya uyumlu büyük cikletlerle bakılabilir.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "500 L"], ["Huy", "Yarı agresif–agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "İri Yapılı, Nadir Tür"]]'::jsonb,array['vieja regani','regani vieja','vieja cichlid','regani cichlid']::text[],true,'published'),
('maskaheros-argenteus','Argentea','Maskaheros argenteus','orta-amerika','fish','Zor','Agresif','Gümüş-beyaz gövdesi üzerindeki siyah lekeleriyle son derece karakteristik büyük bir ciklettir. Yavaş büyür fakat erişkin olduğunda geniş hacim ister.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "700 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor, bitkisel ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Nadir Tür, İri Yapılı"]]'::jsonb,array['argentea','maskaheros argenteus','vieja argentea','silver cichlid']::text[],true,'published'),
('maskaheros-regani','Regal Cichlid','Maskaheros regani','orta-amerika','fish','Zor','Agresif','İri gövdesi ve belirgin desenleriyle tanınan nadir bir Meksika cikletidir. Yetişkin boyutu ve bölgeciliği nedeniyle geniş tank gerektirir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "700 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Nadir Tür, İri Yapılı"]]'::jsonb,array['regal cichlid','maskaheros regani','regani cichlid','vieja regani old name','maskaheros']::text[],true,'published'),
('parachromis-motaguensis','Motaguensis / Red Tiger','Parachromis motaguensis','orta-amerika','fish','Zor','Çok agresif, avcı','Kırmızı-turuncu karın bölgesi ve siyah lekeleriyle gösterişli bir yırtıcıdır. Çok güçlü avcılık ve bölgecilik davranışı gösterir.','[["Yetişkin boy", "35 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "600 L"], ["Huy", "Çok agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Avcı, Agresif"]]'::jsonb,array['motaguensis / red tiger','motaguensis','parachromis motaguensis','red tiger mota','mota cichlid']::text[],true,'published'),
('parachromis-managuensis','Jaguar Cichlid','Parachromis managuensis','orta-amerika','fish','Orta','Çok agresif, avcı','Jaguar benzeri siyah desenleriyle tanınan çok iri bir avcı ciklettir. Küçük balıkları avlar ve erişkinlerde büyük hacim gerektirir.','[["Yetişkin boy", "40 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "700 L"], ["Huy", "Çok agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Avcı, İri Yapılı"]]'::jsonb,array['jaguar cichlid','parachromis managuensis','managuensis','jaguar ciklet']::text[],false,'published'),
('parachromis-dovii','Dovii / Wolf Cichlid','Parachromis dovii','orta-amerika','fish','Zor','Aşırı agresif, avcı','Orta Amerika''nın en iri ve güçlü avcı cikletlerinden biridir. Boyutu, agresyonu ve yüzme alanı ihtiyacı nedeniyle yalnızca çok büyük akvaryumlara uygundur.','[["Yetişkin boy", "70 cm"], ["Sıcaklık", "24–30 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "1200 L"], ["Huy", "Aşırı agresif, avcı"], ["Beslenme", "Etçil"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Dev Ciklet, Avcı"]]'::jsonb,array['dovii / wolf cichlid','dovii','parachromis dovii','wolf cichlid','kurt ciklet']::text[],true,'published'),
('parachromis-friedrichsthalii','Friedrichsthalii / Yellow Jacket','Parachromis friedrichsthalii','orta-amerika','fish','Zor','Agresif, avcı','Sarı zemin üzerindeki koyu desenleriyle tanınan büyük bir Parachromis türüdür. Avcı ve bölgeci yapısı nedeniyle güçlü tank arkadaşları ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "500 L"], ["Huy", "Agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Avcı, Nadir Tür"]]'::jsonb,array['friedrichsthalii / yellow jacket','friedrichsthalii','parachromis friedrichsthalii','yellow jacket cichlid','freddy cichlid']::text[],true,'published'),
('parachromis-loisellei','Loisellei','Parachromis loisellei','orta-amerika','fish','Orta','Agresif, avcı','Sarı-altın gövdesi ve koyu yatay deseniyle diğer Parachromis türlerinden ayrılır. Cins içinde görece küçük kalsa da belirgin avcı karakteri taşır.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "400 L"], ["Huy", "Agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Avcı, Renkli"]]'::jsonb,array['parachromis loisellei','loisellei','yellow guapote','loisellei cichlid']::text[],true,'published'),
('nosferatu-istlanum','Istlanum','Nosferatu istlanum','orta-amerika','fish','Zor','Agresif','Meksika''nın Balsas havzasına özgü, güçlü ve bölgeci bir ciklettir. Nadirliği ve sert karakteri nedeniyle deneyimli hobicilere daha uygundur.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "400 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Nadir Tür, Bölgeci"]]'::jsonb,array['ıstlanum','nosferatu istlanum','istlanum','cichlasoma istlanum','balsas cichlid']::text[],true,'published'),
('nosferatu-beani','Beani / Green Guapote','Nosferatu beani','orta-amerika','fish','Zor','Çok agresif','Meksika Pasifik kıyılarına özgü, iri ve agresif bir ciklettir. Yüksek sıcaklık ve kötü su kalitesine toleransı sınırlı olabileceğinden stabil bakım ister.','[["Yetişkin boy", "30 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "500 L"], ["Huy", "Çok agresif"], ["Beslenme", "Omnivor, etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Nadir Tür, Agresif"]]'::jsonb,array['beani / green guapote','nosferatu beani','beani','green guapote','cichlasoma beani']::text[],true,'published'),
('chiapaheros-grammodes','Grammodes / Mini Dovii','Chiapaheros grammodes','orta-amerika','fish','Zor','Çok agresif, avcı','Uzun çenesi ve avcı görünümü nedeniyle ''Mini Dovii'' adıyla bilinir. Boyuna göre son derece sert ve bölgeci olabilir.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "400 L"], ["Huy", "Çok agresif, avcı"], ["Beslenme", "Etçil ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Avcı, Agresif"]]'::jsonb,array['grammodes / mini dovii','grammodes','chiapaheros grammodes','mini dovii','cichlasoma grammodes']::text[],true,'published'),
('herichthys-pantostictus','Pearl Cichlid / Pantano','Herichthys pantostictus','orta-amerika','fish','Orta','Agresif','Mavi-yeşil inci desenleri ve değişken gövde rengiyle dikkat çeker. Doğal popülasyon kimliği korunması gereken bir Herichthys türüdür.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.0–8.5"], ["Min. akvaryum", "350 L"], ["Huy", "Agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Bölgeci"]]'::jsonb,array['pearl cichlid / pantano','herichthys pantostictus','pantostictus','pearl cichlid','herichthys']::text[],true,'published'),
('herichthys-minckleyi','Minckleyi','Herichthys minckleyi','orta-amerika','fish','Zor','Yarı agresif','Meksika''daki Cuatro Ciénegas havzasına özgü, farklı beslenme morflarıyla bilimsel açıdan da ilginç bir ciklettir. Hobi piyasasında oldukça enderdir.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "300 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor; morfa göre değişken"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Nadir Tür, Endemik"]]'::jsonb,array['herichthys minckleyi','minckleyi','cuatro cienegas cichlid','herichthys']::text[],true,'published'),
('thorichthys-deppii','Deppii','Thorichthys deppii','orta-amerika','fish','Orta','Yarı agresif','Firemouth akrabası olan, ince yapılı ve zarif bir Thorichthys türüdür. Benzer boydaki sakin-orta karakterli balıklarla daha uyumludur.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "180 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, küçük omurgasız ağırlıklı"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Zarif, Bölgeci"]]'::jsonb,array['deppii','thorichthys deppii','deppii cichlid','deppi','thorichthys']::text[],true,'published'),
('thorichthys-maculipinnis','Ellioti / Maculipinnis','Thorichthys maculipinnis','orta-amerika','fish','Orta','Yarı agresif','Turuncu-kırmızı karın ve mavi benekleriyle Firemouth''a benzeyen gösterişli bir türdür. Kumluk taban ve açık yüzme alanlarından yararlanır.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "180 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Orta Boy"]]'::jsonb,array['ellioti / maculipinnis','ellioti','thorichthys maculipinnis','maculipinnis','ellioti cichlid']::text[],false,'published'),
('thorichthys-helleri','Helleri','Thorichthys helleri','orta-amerika','fish','Orta','Yarı agresif','Sarı-altın gövdesi ve ince mavi desenleriyle tanınan zarif bir Thorichthys türüdür. Sert büyük cikletlerden uzak tutulmalıdır.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "180 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Nadir Tür"]]'::jsonb,array['thorichthys helleri','helleri cichlid','yellow thorichthys','helleri']::text[],true,'published'),
('thorichthys-pasionis','Pasionesis','Thorichthys pasionis','orta-amerika','fish','Orta','Yarı agresif','Sarımsı gövde, kırmızı tonlar ve koyu yan lekeyle tanınan bir Thorichthys türüdür. Grup içinde hiyerarşi kurabilir fakat dev cikletler kadar sert değildir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "180 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Orta Boy, Nadir Tür"]]'::jsonb,array['pasionesis','thorichthys pasionis','pasionis cichlid','yellow meeki','thorichthys']::text[],true,'published'),
('thorichthys-aureus','Aureus','Thorichthys aureus','orta-amerika','fish','Orta','Yarı agresif','Altın gövde tonları ve mavi ışıltılarıyla dikkat çeken bir Thorichthys türüdür. Doğru tank arkadaşlarıyla görece sakin bir Orta Amerika kurulumu oluşturabilir.','[["Yetişkin boy", "15 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "180 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Renkli, Nadir Tür"]]'::jsonb,array['thorichthys aureus','aureus cichlid','blue flash thorichthys','aureus']::text[],true,'published'),
('cribroheros-robertsoni','Robertsoni','Cribroheros robertsoni','orta-amerika','fish','Orta','Yarı agresif','Kum ve ince tabanı eleyerek beslenen, yüksek gövdeli bir Orta Amerika cikletidir. Geniş taban alanı ve güçlü filtrasyon ister.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "350 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, dip omurgasızları"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Kum Eleyen, Orta Büyük"]]'::jsonb,array['cribroheros robertsoni','robertsoni','cichlasoma robertsoni','false firemouth']::text[],true,'published'),
('cribroheros-longimanus','Longimanus','Cribroheros longimanus','orta-amerika','fish','Orta','Yarı agresif','Kumluk alanlarda beslenen, uzun yüzgeçli ve iri bir Cribroheros türüdür. Dip alanını aktif kullandığından geniş taban ölçüsü önemlidir.','[["Yetişkin boy", "25 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "7.0–8.2"], ["Min. akvaryum", "350 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor, dip omurgasızları"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Kum Eleyen, Nadir Tür"]]'::jsonb,array['cribroheros longimanus','longimanus','cichlasoma longimanus','longfin cichlid']::text[],true,'published'),
('cribroheros-alfari','Alfari','Cribroheros alfari','orta-amerika','fish','Orta','Yarı agresif','Kumluk ve akıntılı habitatlara uyumlu, nispeten zarif bir Orta Amerika cikletidir. Doğal davranışları için ince kum ve açık dip alanı faydalıdır.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "250 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Kum Eleyen, Nadir Tür"]]'::jsonb,array['alfari','cribroheros alfari','alfari cichlid','cichlasoma alfari','cribroheros']::text[],true,'published'),
('amatitlania-septemfasciata','Septemfasciatus','Amatitlania septemfasciata','orta-amerika','fish','Kolay','Yarı agresif, bölgeci','Dikey bantlı, kompakt fakat karakterli bir Amatitlania türüdür. Convict akrabaları gibi kolay eşleşebilir ve yavrularını güçlü biçimde korur.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif, bölgeci"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Dayanıklı, Çizgili"]]'::jsonb,array['amatitlania septemfasciata','septemfasciatus','seven stripe cichlid','convict relative']::text[],true,'published'),
('amatitlania-kanna','Kanna','Amatitlania kanna','orta-amerika','fish','Kolay','Yarı agresif','Panama kökenli küçük-orta boy bir Amatitlania türüdür. Güçlü ebeveynlik davranışı gösterir ve üreme döneminde bölgecileşir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "23–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Yarı agresif"], ["Beslenme", "Omnivor"], ["Üreme", "Substrat yumurtlayıcısı"], ["Köken", "Orta Amerika"], ["Özellikler", "Çift Yaşayan, Nadir Tür"]]'::jsonb,array['amatitlania kanna','kanna cichlid','convict type cichlid','kanna']::text[],true,'published')
